function mergeCast(parts,name){const groups=new Map();for(const m of parts){const k=JSON.stringify([m.material.color,m.material.emissive||null]);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(m);}return [...groups.values()].map(items=>{const p=[],n=[],uv=[];for(const m of items){for(const x of m.p)p.push(x);for(const x of m.n)n.push(x);for(const x of m.uv)uv.push(x);}return makeMesh(name,p,uv,n,items[0].material);});}
function ellipsoid(name,c,r,color,N=12,R=8){const p=[],n=[],uv=[];const point=(i,j)=>{const t=i/N*Math.PI*2,f=j/R*Math.PI,v=[Math.cos(t)*Math.sin(f),Math.cos(f),Math.sin(t)*Math.sin(f)];return {p:v.map((x,k)=>c[k]+x*r[k]),n:M.norm(v.map((x,k)=>x/r[k])),uv:[i/N,j/R]};};for(let j=0;j<R;j++)for(let i=0;i<N;i++){const a=point(i,j),b=point(i+1,j),d=point(i,j+1),c=point(i+1,j+1);for(const q of [a,b,c,a,c,d]){p.push(...q.p);n.push(...q.n);uv.push(...q.uv);}}return makeMesh(name,p,uv,n,{color});}
