function torso(profile,color,N=14){const p=[],n=[],uv=[];for(let j=0;j<profile.length-1;j++)for(let i=0;i<N;i++){const a=profile[j],b=profile[j+1],ta=i/N*2*Math.PI,tb=(i+1)/N*2*Math.PI,q=[[Math.cos(ta)*a[1],a[0],Math.sin(ta)*a[2]],[Math.cos(tb)*a[1],a[0],Math.sin(tb)*a[2]],[Math.cos(tb)*b[1],b[0],Math.sin(tb)*b[2]],[Math.cos(ta)*b[1],b[0],Math.sin(ta)*b[2]]];for(const k of [0,1,2,0,2,3]){p.push(...q[k]);const t=k===0||k===3?ta:tb;n.push(Math.cos(t),0,Math.sin(t));uv.push(k/3,j/profile.length);}}return makeMesh('Tailored jacket',p,uv,n,{color});}
